    Ok(t) => t,
    // A FileDirectory conflict was already pushed above; the best-effort tree is ours.
    Err(ag_tree::TreeError::FileDirectoryConflict { .. }) => ours.clone(),
    Err(e) => return Err(e.into()),
};
